from typing import List
import math
from functools import reduce

def maxLength(nums: List[int]) -> int:
    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    def lcm(a: int, b: int) -> int:
        return a * b // gcd(a, b)

    n = len(nums)
    if nums and all(value == nums[0] for value in nums):
        return len(nums)

    max_length = 0

    for i in range(n):
        current_gcd = nums[i]
        current_lcm = nums[i]
        product = nums[i]  # Start with product as nums[i]
        for j in range(i, n):
            if j > i:
                product *= nums[j]
                current_gcd = gcd(current_gcd, nums[j])
                current_lcm = lcm(current_lcm, nums[j])
            if product == current_gcd * current_lcm:
                max_length = max(max_length, j - i + 1)

    return max_length

