from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    position = 0
    for i in range(len(grid)):
        if i % 2 == 0:
            # Even row index: traverse left to right
            for j in range(len(grid[i])):
                if position % 2 == 0:
                    result.append(grid[i][j])
                position += 1
        else:
            # Odd row index: traverse right to left
            for j in range(len(grid[i]) - 1, -1, -1):
                if position % 2 == 0:
                    result.append(grid[i][j])
                position += 1
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first_digit = int(s[i])
            second_digit = int(s[i + 1])
            if counts[s[i]] == first_digit and (counts[s[i + 1]] == second_digit or s[i + 1] == '9'):
                return s[i] + s[i + 1]
    return ''

