def calculateScore(s: str) -> int:
    score = 0
    stacks = [[] for _ in range(26)]  # 26 stacks for each letter
    for i in range(len(s)):
        char_index = ord(s[i]) - ord('a')
        mirror_index = 25 - char_index  # Calculate mirror index
        if char_index < 13:
            stacks[char_index].append(i)  # Only store lower-half letters
        elif stacks[mirror_index]:
            j = stacks[mirror_index].pop()  # Get the closest unmarked index for the mirror
            score += i - j  # Update score
    return score

from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]
    if coins[0][0] < 0:
        dp[0][0][1] = 0

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k is the number of robbers neutralized
                if i == 0 and j == 0:
                    continue
                if i > 0:
                    new_coins = dp[i-1][j][k] + coins[i][j]
                    if coins[i][j] < 0 and k > 0:
                        new_coins = max(new_coins, dp[i-1][j][k-1])
                    dp[i][j][k] = max(dp[i][j][k], new_coins)
                if j > 0:
                    new_coins = dp[i][j-1][k] + coins[i][j]
                    if coins[i][j] < 0 and k > 0:
                        new_coins = max(new_coins, dp[i][j-1][k-1])
                    dp[i][j][k] = max(dp[i][j][k], new_coins)

    return max(dp[m-1][n-1])

