def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[float('inf')] * 3 for _ in range(n)]

    # Initialize the first house costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the dp table for both halves
    for i in range(1, n):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + cost[i][j])

    # Calculate the minimum cost by ensuring equidistant condition
    # Considering second half.
    for i in range(n // 2, n):
        for j in range(3):
            for k in range(3):
                if j != k and j != (5 - k):
                    dp[i][j] = min(dp[i][j], dp[n - 1 - i][k] + cost[i][j])

    # The answer is the minimum cost of painting the last house
    return min(dp[n - 1])

